import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { Box, Typography, Button, CircularProgress } from "@mui/material";
import { supabase } from "../supabase";

const VerifyPage = () => {
  const [status, setStatus] = useState("checking");
  const navigate = useNavigate();

  useEffect(() => {
    const verifyUser = async () => {
      console.log("🔍 Starting verification...");

      // ✅ Check if URL has access token, refresh token, type, etc.
      const urlHash = window.location.hash;
      console.log("📌 URL Hash:", urlHash);

      if (!urlHash || !urlHash.includes("access_token")) {
        console.warn("⚠️ No access_token found in URL hash!");
        setStatus("failed");
        return;
      }

      try {
        console.log("🚀 Attempting to exchange code for session...");
        const { error } = await supabase.auth.exchangeCodeForSession();

        if (error) {
          console.error("❌ exchangeCodeForSession error:", error.message);
          setStatus("failed");
          return;
        }

        console.log("✅ Code exchanged. Fetching user...");

        await new Promise((res) => setTimeout(res, 500)); // give time for session storage

        const { data, error: userError } = await supabase.auth.getUser();

        if (userError || !data?.user) {
          console.error("❌ Failed to fetch user:", userError?.message);
          setStatus("failed");
          return;
        }

        console.log("🎉 User verified:", data.user.email);
        setStatus("success");

        setTimeout(() => {
          navigate("/dashboard");
        }, 2000);
      } catch (err) {
        console.error("🔥 Unexpected error:", err);
        setStatus("failed");
      }
    };

    verifyUser();
  }, [navigate]);

  return (
    <Box
      sx={{
        height: "100vh",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        flexDirection: "column",
        textAlign: "center",
        px: 3,
      }}
    >
      {status === "checking" && (
        <>
          <CircularProgress sx={{ color: "#8E2839", mb: 2 }} />
          <Typography variant="h6" color="#8E2839">
            Verifying your account...
          </Typography>
        </>
      )}

      {status === "success" && (
        <>
          <Typography variant="h6" color="green" mb={1}>
            ✅ Verification successful!
          </Typography>
          <Typography>Redirecting to your dashboard...</Typography>
        </>
      )}

      {status === "failed" && (
        <>
          <Typography variant="h6" color="red" mb={1}>
            ❌ Verification failed
          </Typography>
          <Typography mb={2}>
            Make sure you clicked the link in the same browser where you signed up.
          </Typography>
          <Button
            variant="contained"
            sx={{ backgroundColor: "#8E2839" }}
            onClick={() => navigate("/signin")}
          >
            Back to Sign In
          </Button>
        </>
      )}
    </Box>
  );
};

export default VerifyPage;
